-- ============================================================================
-- v1410: Sample values — Architecture Reviews (v1409) for the demo project
-- ============================================================================
-- Owner request 2026-11-11: fills the 10 Architecture Reviews records seeded by v1374 for SEED334-PRJ-08
-- (fictional Northbridge Bank core banking replacement) with review details, participants, ratings,
-- findings, actions and outcomes. Dated around today (11 Nov 2026): six reviews are held, one is in
-- progress today, two are scheduled and the go-live sign-off review is requested.
-- Records: reviews 10.
-- Only records still untouched (field_values empty) are filled, so a user's edits are never overwritten.
-- Vendor-neutral (rule 26), person fields are plain text. Calculated values use the same rules as the app.
-- Prerequisites: v1409. Idempotent.
-- ============================================================================

UPDATE public.local_register_records r
SET field_values = v.vals::jsonb, status = v.status, description = v.description, updated_at = NOW()
FROM (VALUES
  ('00000000-0000-4000-a022-000000000001', 'complete', 'Held 9 March 2026 by the design authority. Baseline of both legacy cores and the target capability map accepted with three actions. Chair: Ravi Pillai.', $j${"review_reference":"NRB-ARB-01","review_type":"concept","review_body":"design_authority","architecture_domains":["business","application","technology"],"delivery_stage":"initiation","review_date":"2026-03-09","chair":"Ravi Pillai","presenter":"Ravi Pillai","review_scope":"Baseline of the two legacy core instances, the target capability map and the programme architecture principles.","questions_for_board":"Is the capability map complete for Release 1?\nAre the architecture principles agreed as binding for the programme?","artefacts_reviewed":"Enterprise architecture baseline\t0.4\tNRB-EA-01\nTarget capability map\t0.3\tNRB-EA-02\nProgramme architecture principles\t1.0\tNRB-EA-PR-01","related_decisions":"NRB-ADR-03\t8-digit customer number standard","participants":"Ravi Pillai\tChief architect (chair)\tAttended\nGrace Moyo\tProgramme director\tAttended\nNadia Rahman\tSecurity architect\tAttended\nCatherine Mwangi\tTest lead\tAttended\nDaniel Okafor\tExecutive sponsor\tAttended","quorum_met":true,"compliance_checks":"Reuse the target core before building\tCompliant\tCapability map shows no custom build for Release 1\nOne customer, one number\tCompliant\tCustomer number standard proposed\nEvery interface has a named owner\tPartly compliant\tFour interfaces still unowned","strategic_fit":4,"standards_compliance":4,"security_rating":3,"resilience_rating":3,"supportability_rating":4,"findings":"Four interfaces have no named owner\tMedium\tIntegration\nBatch window for end of day not yet sized\tMedium\tTechnology / Infrastructure\nCapability map omits trade finance\tObservation\tBusiness","actions":"Name an owner for every interface\tBrian Otieno\t2026-03-27\tDone\nSize the end-of-day batch window\tRavi Pillai\t2026-04-10\tDone\nConfirm trade finance is out of Release 1\tGrace Moyo\t2026-03-20\tDone","risks_raised":"Batch window too short for two migrated books\tMedium\tSize early and test in Mock 1","outcome":"approved_conditions","conditions":"Interface owners named before the solution design review","decision_by":"Ravi Pillai","minutes_reference":"NRB-DA-MIN-2026-03","next_review_date":"2026-04-13","notes":"All three actions closed before the April review.","architecture_score":72}$j$),
  ('00000000-0000-4000-a022-000000000002', 'complete', 'Held 13 April 2026. Solution architecture for the target core accepted and non-functional targets confirmed for payments and channels. Chair: Ravi Pillai.', $j${"review_reference":"NRB-ARB-02","review_type":"design","review_body":"architecture_board","architecture_domains":["application","technology","security"],"delivery_stage":"design","review_date":"2026-04-13","chair":"Ravi Pillai","presenter":"Ravi Pillai","review_scope":"Solution architecture for the target core, hosting model and non-functional targets for payments and channels.","questions_for_board":"Are the availability and throughput targets right for payments?\nIs the hosting model accepted by security?","artefacts_reviewed":"Solution architecture\t0.6\tNRB-SA-01\nNon-functional requirements\t1.1\tNRB-NFR-01\nHosting model\t0.2\tNRB-SA-02","related_decisions":"NRB-ADR-02\tStore mandate and signature images in a file store\nNRB-ADR-10\tStore mandate images in the core database (superseded)","participants":"Ravi Pillai\tChief architect (chair)\tAttended\nGrace Moyo\tProgramme director\tAttended\nNadia Rahman\tSecurity architect\tAttended\nCatherine Mwangi\tTest lead\tAttended\nDaniel Okafor\tExecutive sponsor\tApologies\nAhmed Hassan\tOperations lead\tAttended","quorum_met":true,"compliance_checks":"Reuse the target core before building\tCompliant\tNo custom modules\nSecurity controls designed in\tCompliant\tHosting model reviewed by security\nAvailability 99.9% for payments\tCompliant\tActive-passive design meets the target","strategic_fit":5,"standards_compliance":4,"security_rating":4,"resilience_rating":4,"supportability_rating":4,"findings":"Image storage in the core database would breach the size limit\tHigh\tData\nRecovery time for payments not yet tested\tMedium\tTechnology / Infrastructure","actions":"Move mandate images to a file store (decision NRB-ADR-02)\tRavi Pillai\t2026-04-30\tDone\nPlan a recovery test for payments\tCatherine Mwangi\t2026-07-20\tDone","risks_raised":"Recovery time not proven before the dress rehearsal\tMedium\tRecovery test in the environments review","outcome":"approved","decision_by":"Ravi Pillai","minutes_reference":"NRB-ARB-MIN-2026-04","next_review_date":"2026-05-18","architecture_score":84}$j$),
  ('00000000-0000-4000-a022-000000000003', 'complete', 'Held 18 May 2026. Customer master and channel access design accepted subject to the survivor rule decision. Presenter: Amina Diallo.', $j${"review_reference":"NRB-ARB-03","review_type":"design","review_body":"design_authority","architecture_domains":["data","application","security"],"delivery_stage":"design","review_date":"2026-05-18","chair":"Ravi Pillai","presenter":"Amina Diallo","review_scope":"Customer master design, duplicate handling and how customers sign in to internet and mobile banking on day one.","questions_for_board":"Which record survives when two customers are merged?\nDo customers keep their digital sign-in after go-live?","artefacts_reviewed":"Customer data architecture\t0.5\tNRB-DA-01\nChannel access design\t0.4\tNRB-AA-03","related_decisions":"NRB-ADR-01\tSurvivor rule for duplicate customers\nNRB-ADR-03\t8-digit customer number standard","participants":"Ravi Pillai\tChief architect (chair)\tAttended\nGrace Moyo\tProgramme director\tAttended\nNadia Rahman\tSecurity architect\tAttended\nCatherine Mwangi\tTest lead\tAttended\nAmina Diallo\tCustomer data lead\tAttended\nBrian Otieno\tChannel analyst\tAttended","quorum_met":true,"compliance_checks":"One customer, one number\tCompliant\tSurvivor rule keeps one number\nData cleansed at source\tPartly compliant\tAddress completeness at 82%\nSecurity controls designed in\tCompliant\tSign-in keeps existing credentials","strategic_fit":4,"standards_compliance":4,"security_rating":4,"resilience_rating":3,"supportability_rating":4,"findings":"Survivor rule not yet agreed by the business\tHigh\tData\nAddress completeness below the 85% target\tMedium\tData","actions":"Agree the survivor rule with retail banking\tAmina Diallo\t2026-06-05\tDone\nCleanse addresses at source in the branches\tAmina Diallo\t2026-08-31\tDone","risks_raised":"Duplicates merged onto the wrong survivor\tHigh\tBusiness sign-off of the survivor rule and Mock 1 checks","outcome":"approved_conditions","conditions":"Survivor rule signed off by retail banking before Mock 1","decision_by":"Ravi Pillai","minutes_reference":"NRB-DA-MIN-2026-05","next_review_date":"2026-06-22","architecture_score":76}$j$),
  ('00000000-0000-4000-a022-000000000004', 'complete', 'Held 22 June 2026. Twelve in-scope interfaces reviewed. Card status and trial-balance test slots raised as actions. Presenter: Brian Otieno.', $j${"review_reference":"NRB-ARB-04","review_type":"design","review_body":"technical_design_authority","architecture_domains":["integration","application"],"delivery_stage":"design","review_date":"2026-06-22","chair":"Ravi Pillai","presenter":"Brian Otieno","review_scope":"The twelve in-scope interfaces, their contracts, owners and monitoring.","questions_for_board":"Does every interface have a contract and an owner?\nHow will interface failures be seen on Day 1?","artefacts_reviewed":"Integration architecture\t0.7\tNRB-IA-01\nInterface catalogue\t1.0\tNRB-IA-02","related_decisions":"NRB-ADR-09\tOne dashboard for every interface","participants":"Ravi Pillai\tChief architect (chair)\tAttended\nGrace Moyo\tProgramme director\tAttended\nNadia Rahman\tSecurity architect\tAttended\nCatherine Mwangi\tTest lead\tAttended\nBrian Otieno\tIntegration lead\tAttended\nPriya Naidoo\tInterface analyst\tAttended","quorum_met":true,"compliance_checks":"Every interface has a named owner and a contract\tCompliant\tAll twelve owned\nMonitoring for every interface\tPartly compliant\tCard status feed not yet on the dashboard","strategic_fit":4,"standards_compliance":4,"security_rating":4,"resilience_rating":3,"supportability_rating":3,"findings":"Card status feed has no test slot\tMedium\tIntegration\nTrial-balance feed to finance not in the SIT plan\tMedium\tIntegration","actions":"Book a card status test slot in SIT\tCatherine Mwangi\t2026-07-15\tDone\nAdd the trial-balance feed to the SIT plan\tCatherine Mwangi\t2026-07-15\tDone\nPut the card status feed on the interface dashboard\tBrian Otieno\t2026-08-14\tDone","risks_raised":"Card status out of step after cutover\tMedium\tReconcile card status in each mock","outcome":"approved_conditions","conditions":"Card status and trial-balance feeds tested in SIT","decision_by":"Ravi Pillai","minutes_reference":"NRB-TDA-MIN-2026-06","next_review_date":"2026-07-20","architecture_score":72}$j$),
  ('00000000-0000-4000-a022-000000000005', 'actions_open', 'Held 20 July 2026. Environment path accepted. Masked data refresh and recovery restore raised as conditions, one still open. Presenter: Ravi Pillai.', $j${"review_reference":"NRB-ARB-05","review_type":"compliance","review_body":"technical_design_authority","architecture_domains":["technology","security","data"],"delivery_stage":"build","review_date":"2026-07-20","chair":"Grace Moyo","presenter":"Ravi Pillai","review_scope":"Environment path from development to production, release process, test data and recovery.","questions_for_board":"Is masked production-like data available in test?\nHas a restore from backup been proven?","artefacts_reviewed":"Environment strategy\t0.5\tNRB-ENV-01\nRelease process\t0.3\tNRB-REL-01","related_decisions":"NRB-ADR-08\tMasked production-like data in lower environments","participants":"Ravi Pillai\tChief architect (chair)\tAttended\nGrace Moyo\tProgramme director\tAttended\nNadia Rahman\tSecurity architect\tAttended\nCatherine Mwangi\tTest lead\tAttended\nAhmed Hassan\tOperations lead\tDelegate sent","quorum_met":true,"compliance_checks":"Masked data in lower environments\tPartly compliant\tMasking tool in place, refresh not yet scheduled\nRecovery restore proven\tNot compliant\tNo restore test yet\nRelease through a controlled path\tCompliant\tFour-stage path agreed","strategic_fit":4,"standards_compliance":3,"security_rating":3,"resilience_rating":2,"supportability_rating":4,"findings":"No restore from backup proven in the pre-production environment\tHigh\tTechnology / Infrastructure\nMasked data refresh not on a schedule\tMedium\tData","actions":"Schedule a monthly masked data refresh\tRavi Pillai\t2026-08-31\tDone\nProve a full restore in pre-production\tAhmed Hassan\t2026-11-27\tIn Progress","risks_raised":"Restore fails during the dress rehearsal\tHigh\tRestore test before Mock 2","outcome":"approved_conditions","conditions":"Masked data refreshed monthly\nFull restore proven in pre-production before Mock 2","decision_by":"Grace Moyo","minutes_reference":"NRB-TDA-MIN-2026-07","next_review_date":"2026-11-27","notes":"The restore test moved from September to November because the pre-production environment was late.","architecture_score":64}$j$),
  ('00000000-0000-4000-a022-000000000006', 'actions_open', 'Held 12 October 2026. Mock 1 overrun and take-over balances reviewed. Three mocks plus a dress rehearsal confirmed. Presenter: Priya Naidoo.', $j${"review_reference":"NRB-ARB-06","review_type":"compliance","review_body":"design_authority","architecture_domains":["data","technology"],"delivery_stage":"test","review_date":"2026-10-12","chair":"Ravi Pillai","presenter":"Priya Naidoo","review_scope":"Mock 1 results, the load overrun, take-over balance reconciliation and the plan for the remaining mocks.","questions_for_board":"Can the load fit the cutover window?\nDo take-over balances reconcile to the legacy ledgers?","artefacts_reviewed":"Data migration architecture\t0.8\tNRB-DM-01\nMock 1 report\t1.0\tNRB-DM-M1\nCBS data migration runbook\t0.9\tNRB-DM-RB","related_decisions":"NRB-ADR-07\tThree mock migrations and one dress rehearsal\nNRB-ADR-05\tRecreate standing orders instead of replaying them","participants":"Ravi Pillai\tChief architect (chair)\tAttended\nGrace Moyo\tProgramme director\tAttended\nNadia Rahman\tSecurity architect\tAttended\nCatherine Mwangi\tTest lead\tAttended\nPriya Naidoo\tData migration lead\tAttended\nAhmed Hassan\tOperations lead\tAttended","quorum_met":true,"compliance_checks":"Data cleansed at source, not in the load\tPartly compliant\tTwo load-time fixes remain\nLoad fits the cutover window\tNot compliant\tMock 1 ran 3 hours over","strategic_fit":4,"standards_compliance":3,"security_rating":4,"resilience_rating":2,"supportability_rating":3,"findings":"Mock 1 load ran 3 hours over the window\tHigh\tData\nTake-over balances off by 0.02% on loans\tMedium\tData","actions":"Run loan and deposit loads in parallel\tPriya Naidoo\t2026-11-20\tIn Progress\nFind and fix the loan balance difference\tJoy Akinyi\t2026-11-20\tOpen\nAdd a timing checkpoint to the runbook\tPriya Naidoo\t2026-10-30\tDone","risks_raised":"Cutover load overruns the weekend window\tHigh\tParallel loads proven in Mock 2","outcome":"approved_conditions","conditions":"Mock 2 load finishes inside the window\nLoan balances reconcile to zero difference","decision_by":"Ravi Pillai","minutes_reference":"NRB-DA-MIN-2026-10","next_review_date":"2026-12-14","architecture_score":64}$j$),
  ('00000000-0000-4000-a022-000000000007', 'in_progress', 'In progress today, 11 November 2026. Expired-limit rule and collateral load order reviewed before Mock 2. Presenter: Joy Akinyi.', $j${"review_reference":"NRB-ARB-07","review_type":"design","review_body":"design_authority","architecture_domains":["data","application"],"delivery_stage":"test","review_date":"2026-11-11","chair":"Ravi Pillai","presenter":"Joy Akinyi","review_scope":"How expired limits that still secure a live contract are migrated, and the load order for collateral.","questions_for_board":"Should expired limits that still secure a live loan be migrated?\nMust collateral load before or after the loans it secures?","artefacts_reviewed":"Lending and collateral design\t0.6\tNRB-AA-05\nCollateral mapping\t0.4\tNRB-DM-07","related_decisions":"NRB-ADR-06\tMigrate expired limits that still secure a live contract","participants":"Ravi Pillai\tChief architect (chair)\tAttended\nGrace Moyo\tProgramme director\tAttended\nNadia Rahman\tSecurity architect\tAttended\nCatherine Mwangi\tTest lead\tAttended\nJoy Akinyi\tLending lead\tAttended\nLinda Zhou\tCollateral analyst\tAttended\nAhmed Hassan\tCredit analyst\tApologies","quorum_met":true,"compliance_checks":"Reuse the target core before building\tCompliant\tStandard limit structure used\nData cleansed at source\tPartly compliant\t118 limits need a business decision","strategic_fit":4,"standards_compliance":4,"security_rating":4,"resilience_rating":3,"supportability_rating":4,"findings":"118 expired limits still secure live loans\tMedium\tData","actions":"Agree the treatment of the 118 limits with credit risk\tJoy Akinyi\t2026-11-20\tOpen","notes":"Outcome to be recorded at the end of the session.","architecture_score":76}$j$),
  ('00000000-0000-4000-a022-000000000008', 'scheduled', 'Planned for 24 November 2026. Restart criteria for the security workstream and the recertification approach. Presenter: Nadia Rahman.', $j${"review_reference":"NRB-ARB-08","review_type":"compliance","review_body":"security_design_authority","architecture_domains":["security","application"],"delivery_stage":"test","review_date":"2026-11-24","chair":"Nadia Rahman","presenter":"Nadia Rahman","review_scope":"Role design in the target core, access recertification before go-live and the restart criteria for the security workstream.","questions_for_board":"Are user roles least-privilege?\nHow will every user be recertified before go-live?","artefacts_reviewed":"Security architecture\t0.5\tNRB-SEC-01\nRole catalogue\t0.3\tNRB-SEC-02","participants":"Nadia Rahman\tSecurity architect (chair)\tInvited\nRavi Pillai\tChief architect\tInvited\nGrace Moyo\tProgramme director\tInvited\nAhmed Hassan\tOperations lead\tInvited"}$j$),
  ('00000000-0000-4000-a022-000000000009', 'scheduled', 'Planned for 22 February 2027. Environment, rollback steps and interface readiness checked before the dress rehearsal. Chair: Ravi Pillai.', $j${"review_reference":"NRB-ARB-09","review_type":"readiness","review_body":"architecture_board","architecture_domains":["technology","integration","data"],"delivery_stage":"pre_go_live","review_date":"2027-02-22","chair":"Ravi Pillai","presenter":"Ahmed Hassan","review_scope":"Production environment, rollback steps, interface readiness and Mock 3 results before the dress rehearsal.","questions_for_board":"Is production built and tested to the design?\nCan the bank roll back within the window?","artefacts_reviewed":"Cutover plan\t1.0\tNRB-CUT-01\nRollback plan\t0.7\tNRB-CUT-02\nMock 3 report\t\tNRB-DM-M3","participants":"Ravi Pillai\tChief architect (chair)\tInvited\nGrace Moyo\tProgramme director\tInvited\nNadia Rahman\tSecurity architect\tInvited\nCatherine Mwangi\tTest lead\tInvited\nAhmed Hassan\tOperations lead\tInvited"}$j$),
  ('00000000-0000-4000-a022-000000000010', 'requested', 'Requested for 29 March 2027. Final architecture sign-off before the 10–12 April 2027 cutover. Chair: Grace Moyo.', $j${"review_reference":"NRB-ARB-10","review_type":"readiness","review_body":"architecture_board","architecture_domains":["business","data","application","integration","technology","security"],"delivery_stage":"pre_go_live","review_date":"2027-03-29","chair":"Grace Moyo","presenter":"Ravi Pillai","review_scope":"Final architecture sign-off: all conditions from earlier reviews closed, waivers confirmed and the production design accepted.","questions_for_board":"Are all earlier conditions closed?\nAre any waivers still needed at go-live?"}$j$)
) AS v(id, status, description, vals)
WHERE r.id = v.id::uuid AND COALESCE(r.field_values, '{}'::jsonb) = '{}'::jsonb;

-- Check: records per register and how many have field values.
SELECT l.register_key, count(r.id) AS records, count(*) FILTER (WHERE r.field_values <> '{}'::jsonb) AS with_values
FROM public.local_registers l
LEFT JOIN public.local_register_records r ON r.register_id = l.id AND r.is_deleted = FALSE
WHERE l.id IN ('00000000-0000-4000-9003-00000000000c'::uuid)
GROUP BY l.register_key ORDER BY l.register_key;
